<script setup lang="ts">
import { computed, ref, watch } from 'vue'
import { useRouter } from 'vue-router'
import { Search, Plus, Trash2, MessageSquare, ChevronLeft, ChevronRight, ArrowUpRight } from 'lucide-vue-next'
import { useWorkspace } from '../stores/workspace'
import ModalPanel from '../components/ModalPanel.vue'
const store = useWorkspace(); const router = useRouter(); const search = ref(''); const page = ref(1); const deleting = ref('')
const filtered = computed(() => [...store.conversations].filter(c => (!search.value || `${c.title} ${c.messages.map(m => m.content).join(' ')}`.toLowerCase().includes(search.value.toLowerCase()))).sort((a, b) => b.updated.localeCompare(a.updated)))
const pages = computed(() => Math.max(1, Math.ceil(filtered.value.length / 8))); const rows = computed(() => filtered.value.slice((page.value - 1) * 8, page.value * 8))
watch(search, () => page.value = 1); watch(pages, value => page.value = Math.min(page.value, value))
function open(id: string) { store.open(id); router.push('/') }
function create() { store.newChat(); router.push('/') }
function format(date: string) { return new Date(date).toLocaleString('zh-CN', { month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit' }) }
function remove() { store.remove(deleting.value); deleting.value = '' }
</script>
<template><div class="page"><div class="page-heading"><div><div class="eyebrow">CONVERSATIONS</div><h1>会话记录</h1><p>回顾每一次交流，随时继续处理。</p></div><button class="button primary" :disabled="store.busy" @click="create"><Plus :size="16" />新建会话</button></div><div class="summary-grid"><div class="summary-card"><span>全部会话</span><strong>{{ store.conversations.length }}<small>个会话</small></strong></div><div class="summary-card"><span>累计交流</span><strong>{{ store.conversations.reduce((sum, c) => sum + c.messages.filter(m => m.role === 'user').length, 0) }}<small>轮对话</small></strong></div><div class="summary-card"><span>数据存储</span><strong class="summary-label">当前浏览器<span class="badge">本地</span></strong></div></div><section class="card history-card"><div class="filter-bar"><label class="search-input"><Search :size="17" /><input v-model="search" aria-label="搜索会话" placeholder="搜索会话标题或消息内容…" /></label><span class="filter-count">{{ filtered.length }} 个会话</span></div><div v-if="!rows.length" class="empty-state"><span class="empty-icon"><MessageSquare :size="25" /></span><h2>{{ store.conversations.length ? '没有找到匹配的会话' : '还没有会话记录' }}</h2><p>{{ store.conversations.length ? '试试其他关键词，或清除筛选条件。' : '从一个问题开始，你的交流会自动保存在这里。' }}</p><button v-if="store.conversations.length" class="button" @click="search = ''">清除筛选</button><button v-else class="button primary" @click="create">开始第一次对话<ArrowUpRight :size="15" /></button></div><div v-else class="table-scroll"><table class="history-table"><thead><tr><th>会话</th><th>消息数</th><th>更新时间</th><th><span class="sr-only">操作</span></th></tr></thead><tbody><tr v-for="c in rows" :key="c.id"><td><button class="conversation-title" :disabled="store.busy" @click="open(c.id)"><span class="small-icon"><MessageSquare :size="16" /></span><span><strong>{{ c.title }}</strong><small>{{ c.messages.filter(m => m.role === 'assistant').at(-1)?.content || '尚未收到回答' }}</small></span></button></td><td data-label="消息数">{{ c.messages.length }}</td><td data-label="更新时间" class="muted">{{ format(c.updated) }}</td><td class="row-actions"><button class="icon-button" aria-label="继续对话" :disabled="store.busy" @click="open(c.id)"><ArrowUpRight :size="17" /></button><button class="icon-button danger-icon" aria-label="删除本地会话" :disabled="store.busy" @click="deleting = c.id"><Trash2 :size="16" /></button></td></tr></tbody></table></div><footer class="pagination"><span>仅包含当前浏览器保存的记录</span><div><span>{{ page }} / {{ pages }}</span><button class="button icon-button" aria-label="上一页" :disabled="page <= 1" @click="page--"><ChevronLeft :size="16" /></button><button class="button icon-button" aria-label="下一页" :disabled="page >= pages" @click="page++"><ChevronRight :size="16" /></button></div></footer></section><ModalPanel v-if="deleting" title="删除本地会话" @close="deleting = ''"><p>删除后无法恢复。此操作仅移除当前浏览器中的记录，不会删除服务端会话或撤销已执行的业务操作。</p><template #footer><button class="button" @click="deleting = ''">保留会话</button><button class="button danger" @click="remove">确认删除</button></template></ModalPanel></div></template>
